#if TEST_BUILD
using System;using System.IO;using System.Linq;using System.Text;using System.Threading;using System.Collections.Generic;using System.Security.Cryptography;
internal static class NameDiagnosticsSmoke {
 static void Require(bool value,string message){if(!value)throw new InvalidOperationException(message);}
 static string Sha(char c){return new string(c,64);}
 static void SetCache(string root,string path){Directory.CreateDirectory(Path.Combine(root,"tests"));File.WriteAllText(Path.Combine(root,"tests","name-cache-root.txt"),path,new UTF8Encoding(false));}
 static void WriteU(byte[] bytes,int offset,uint value){Buffer.BlockCopy(BitConverter.GetBytes(value),0,bytes,offset,4);}
 static void WriteSaved(string root){string dir=Path.Combine(root,"data");Directory.CreateDirectory(dir);var saved=new Dictionary<string,NameEvidence>{{"401000",new NameEvidence{Id="401000",Name="保留名称夹具",Kind="official-local-wallpaper-response",CheckedAt=DateTimeOffset.Now.ToString("o"),SourceBytes=16,SourceSha256=Sha('a'),IndexSha256=Sha('b'),ResponsePath="/pcwallpapercontent/wallpaper/jingling/wallpaperListDynamic",JsonPath="$.data.fixture"}}};Common.SaveNew(Path.Combine(dir,"official-names.json"),saved);}
 static string ReadAll(string path){return File.ReadAllText(path,new UTF8Encoding(false));}
 internal static int Run(string root,string attempt){
  if(String.IsNullOrEmpty(attempt)||attempt.Length>12||!attempt.All(c=>Char.IsLetterOrDigit(c)||c=='-'))throw new ArgumentException("Invalid isolated attempt label.");string evidence=Path.Combine(root,"evidence");Directory.CreateDirectory(evidence);string receipt=Path.Combine(evidence,"name-diagnostics-smoke-"+attempt+".json");if(File.Exists(receipt))throw new IOException("Existing smoke receipt preserved.");
  var results=new List<object>();string nameFile=Path.Combine(root,"data","official-names.json");WriteSaved(root);string savedBefore=ReadAll(nameFile);
  try{
   string missing=Path.Combine(root,"tests","name-cache-missing");SetCache(root,missing);var noCache=OfficialNameStore.Refresh(new[]{"401000"},()=>{});Require(noCache.Diagnostics!=null&&noCache.Diagnostics.Outcome=="cache-missing"&&noCache.Diagnostics.FailureKind=="missing-cache","Missing cache was not classified as a normal optional state");Require(noCache.Names.ContainsKey("401000")&&noCache.Names["401000"].Name=="保留名称夹具","Saved name was lost when cache was absent");Require(ReadAll(nameFile)==savedBefore,"Missing cache changed persistent names");results.Add(new{caseName="missing optional cache",passed=true,outcome=noCache.Diagnostics.Outcome,preservedSavedName=true});

   string damaged=Path.Combine(root,"tests","name-cache-damaged");Directory.CreateDirectory(damaged);SetCache(root,damaged);File.WriteAllBytes(Path.Combine(damaged,"index"),new byte[]{1,2});var bad=OfficialNameStore.Refresh(new[]{"401000"},()=>{});Require(bad.Diagnostics!=null&&bad.Diagnostics.Outcome=="cache-damaged"&&bad.Diagnostics.Stage=="index-validate"&&bad.Diagnostics.FailureKind=="corrupt-cache"&&bad.Diagnostics.IndexBytesRead==2,"Damaged index stage/bytes were not retained");Require(bad.Names["401000"].Name=="保留名称夹具"&&ReadAll(nameFile)==savedBefore,"Damaged cache overwrote saved name");results.Add(new{caseName="damaged index",passed=true,stage=bad.Diagnostics.Stage,failureKind=bad.Diagnostics.FailureKind,indexBytesRead=bad.Diagnostics.IndexBytesRead,preservedSavedName=true});

   string tooLarge=Path.Combine(root,"tests","name-cache-budget");Directory.CreateDirectory(tooLarge);SetCache(root,tooLarge);using(var f=new FileStream(Path.Combine(tooLarge,"index"),FileMode.CreateNew,FileAccess.Write,FileShare.None))f.SetLength(2097153);var over=OfficialNameStore.Refresh(new[]{"401000"},()=>{});Require(over.Diagnostics!=null&&over.Diagnostics.Outcome=="budget-exceeded"&&over.Diagnostics.Stage=="index-read"&&over.Diagnostics.FailureKind=="budget"&&over.Diagnostics.IndexBytesRead==0,"Oversize index was not bounded and classified");Require(over.Names["401000"].Name=="保留名称夹具"&&ReadAll(nameFile)==savedBefore,"Over-budget cache overwrote saved name");results.Add(new{caseName="index over budget",passed=true,stage=over.Diagnostics.Stage,failureKind=over.Diagnostics.FailureKind,preservedSavedName=true});

   string missingEntry=Path.Combine(root,"tests","name-cache-entry-missing");Directory.CreateDirectory(missingEntry);SetCache(root,missingEntry);byte[] entryIndex=new byte[524656];WriteU(entryIndex,0,0xc103cac3);WriteU(entryIndex,4,0x30000);WriteU(entryIndex,8,1);WriteU(entryIndex,28,131072);WriteU(entryIndex,368,0x80000000);File.WriteAllBytes(Path.Combine(missingEntry,"index"),entryIndex);var entryFailure=OfficialNameStore.Refresh(new[]{"401000"},()=>{});Require(entryFailure.Diagnostics.Stage=="index-entry-read"&&entryFailure.Diagnostics.FailureKind=="read-failure"&&entryFailure.Diagnostics.IndexBytesRead==524656,"Missing index entry evidence mismatch");Require(entryFailure.Names["401000"].Name=="保留名称夹具"&&ReadAll(nameFile)==savedBefore,"Entry failure overwrote saved name");results.Add(new{caseName="missing index entry file",passed=true,stage=entryFailure.Diagnostics.Stage,failureKind=entryFailure.Diagnostics.FailureKind,indexBytesRead=entryFailure.Diagnostics.IndexBytesRead,preservedSavedName=true});

   string missingBody=Path.Combine(root,"tests","name-cache-response-missing");Directory.CreateDirectory(missingBody);SetCache(root,missingBody);byte[] responseIndex=(byte[])entryIndex.Clone();WriteU(responseIndex,8,1);File.WriteAllBytes(Path.Combine(missingBody,"index"),responseIndex);byte[] record=new byte[256];WriteU(record,0,0);WriteU(record,4,0);byte[] key=Encoding.UTF8.GetBytes("http://pc-store.lenovomm.cn/pcwallpapercontent/wallpaper/jingling/wallpaperListDynamic");WriteU(record,32,(uint)key.Length);WriteU(record,44,32);WriteU(record,60,0x80000001);Buffer.BlockCopy(key,0,record,96,key.Length);File.WriteAllBytes(Path.Combine(missingBody,"f_000000"),record);var bodyFailure=OfficialNameStore.Refresh(new[]{"401000"},()=>{});Require(bodyFailure.Diagnostics.Stage=="response-read"&&bodyFailure.Diagnostics.FailureStage=="response-read"&&bodyFailure.Diagnostics.FailureKind=="read-failure"&&bodyFailure.Diagnostics.EntryBytesRead==256&&bodyFailure.Diagnostics.ResponseBytesRead==0,"Missing response stage/byte classes were not retained");Require(bodyFailure.Names["401000"].Name=="保留名称夹具"&&ReadAll(nameFile)==savedBefore,"Response failure overwrote saved name");results.Add(new{caseName="missing response body file",passed=true,stage=bodyFailure.Diagnostics.Stage,failureStage=bodyFailure.Diagnostics.FailureKind,entryBytesRead=bodyFailure.Diagnostics.EntryBytesRead,responseBytesRead=bodyFailure.Diagnostics.ResponseBytesRead,preservedSavedName=true});

   string valid=Path.Combine(root,"tests","name-cache-valid-empty");Directory.CreateDirectory(valid);SetCache(root,valid);byte[] validIndex=new byte[524656];WriteU(validIndex,0,0xc103cac3);WriteU(validIndex,4,0x30000);WriteU(validIndex,8,0);WriteU(validIndex,28,131072);File.WriteAllBytes(Path.Combine(valid,"index"),validIndex);var checkedEmpty=OfficialNameStore.Refresh(new[]{"401000"},()=>{});Require(checkedEmpty.Diagnostics.Outcome=="checked-no-match"&&checkedEmpty.Diagnostics.ExceptionType==null&&checkedEmpty.Diagnostics.IndexBytesRead==1049312,"Valid empty index or no-match state was not classified");Require(checkedEmpty.Names["401000"].Name=="保留名称夹具"&&ReadAll(nameFile)==savedBefore,"Valid empty cache overwrote saved name");results.Add(new{caseName="valid empty index/no match",passed=true,outcome=checkedEmpty.Diagnostics.Outcome,indexBytesRead=checkedEmpty.Diagnostics.IndexBytesRead,preservedSavedName=true});
   string unsupported=Path.Combine(root,"tests","name-cache-unsupported-version");Directory.CreateDirectory(unsupported);SetCache(root,unsupported);byte[] unknown=(byte[])validIndex.Clone();WriteU(unknown,4,0x40000);File.WriteAllBytes(Path.Combine(unsupported,"index"),unknown);var unknownResult=OfficialNameStore.Refresh(new[]{"401000"},()=>{});Require(unknownResult.Diagnostics.Outcome=="format-unsupported"&&unknownResult.Diagnostics.FailureKind=="unsupported-format"&&unknownResult.Diagnostics.ValidationField=="version"&&unknownResult.Diagnostics.IndexVersion==0x40000,"Unsupported index version was not identified safely");Require(unknownResult.Names["401000"].Name=="保留名称夹具"&&ReadAll(nameFile)==savedBefore,"Unsupported version overwrote saved name");results.Add(new{caseName="unsupported cache version",passed=true,validationField=unknownResult.Diagnostics.ValidationField,version=unknownResult.Diagnostics.IndexVersion,preservedSavedName=true});

   string timeout=Path.Combine(root,"tests","name-cache-timeout");Directory.CreateDirectory(timeout);SetCache(root,timeout);OfficialNames.ReadNames(new[]{"401000"},()=>Thread.Sleep(5200));Require(OfficialNames.LastDiagnostics.Outcome=="budget-exceeded"&&OfficialNames.LastDiagnostics.FailureKind=="budget"&&OfficialNames.LastDiagnostics.Stage=="cache-root-check","Timeout did not report bounded stage");Require(ReadAll(nameFile)==savedBefore,"Timeout changed persistent names");results.Add(new{caseName="five-second budget",passed=true,outcome=OfficialNames.LastDiagnostics.Outcome,stage=OfficialNames.LastDiagnostics.Stage,savedNameBytesUnchanged=true});

   string cancelled=Path.Combine(root,"tests","name-cache-cancelled");Directory.CreateDirectory(cancelled);SetCache(root,cancelled);bool cancelledCaught=false;try{OfficialNames.ReadNames(new[]{"401000"},()=>{throw new OperationCanceledException("isolated cancel fixture");});}catch(OperationCanceledException){cancelledCaught=true;}Require(cancelledCaught&&OfficialNames.LastDiagnostics.Outcome=="cancelled"&&OfficialNames.LastDiagnostics.Stage=="cache-root-check","Cancellation was swallowed or not attributed");Require(ReadAll(nameFile)==savedBefore,"Cancellation changed persistent names");results.Add(new{caseName="active cancellation",passed=true,outcome=OfficialNames.LastDiagnostics.Outcome,savedNameBytesUnchanged=true});

   Require(NameQueryEmptyAndPlaceholderRules(),"Automatic name query selector does not restrict itself to registered placeholders");results.Add(new{caseName="empty catalog query scope",passed=true,emptyCatalogRequests=0,registeredPlaceholderRequests=1,candidateAutoNamesExcluded=true});
   Common.SaveNew(receipt,new{schemaVersion=1,classification="TEST_BUILD direct processor tests; no GUI, third-party cache or CWP accessed",passed=true,processId=System.Diagnostics.Process.GetCurrentProcess().Id,savedNamePreservedAcrossAllCases=true,diagnostics=results,formalDataTouched=false,playerStarted=false,thirdPartyComponentLoaded=false});return 0;
  }catch(Exception ex){try{Common.SaveNew(Path.Combine(evidence,"name-diagnostics-smoke-failed-"+attempt+".json"),new{classification="TEST_BUILD direct processor failure; not user interface evidence",processId=System.Diagnostics.Process.GetCurrentProcess().Id,error=ex.ToString(),savedNameFileStillExists=File.Exists(nameFile),formalDataTouched=false,playerStarted=false});}catch{}return 1;}
 }
 static bool NameQueryEmptyAndPlaceholderRules(){var empty=NameFlowQuery(new List<WallpaperItem>());if(empty.Length!=0||ControlWindow.ShouldInspectOfficialNameCache(empty))return false;var item=new WallpaperItem{Id="isolation-item",ResourceId="401000",Name="本地壁纸 401000",RegisteredSha256=Sha('c')};var ids=NameFlowQuery(new[]{item});return ids.Length==1&&ids[0]=="401000"&&ControlWindow.ShouldInspectOfficialNameCache(ids);}
 static string[] NameFlowQuery(IEnumerable<WallpaperItem> items){return ControlWindow.RegisteredNameQueryIds(items);}
}
#endif
